mapper.select:
SELECT tenant_id,user_id,tool_name,operation_id,downstream_id,params_hash,
       params_json,operation_status,response_text,submit_count,lookup_count,
       next_lookup,retry_allowed
FROM side_effect_operations
WHERE tenant_id=#{tenantId} AND user_id=#{userId}
  AND tool_name=#{toolName} AND operation_id=#{operationId}

mapper.update:
UPDATE side_effect_operations SET operation_status='RUNNING',
  submit_count=submit_count+1,retry_allowed=FALSE
WHERE downstream_id=#{downstreamId}

UPDATE side_effect_operations SET operation_status=#{operationStatus},
  response_text=#{responseText},retry_allowed=#{retryAllowed}
WHERE downstream_id=#{downstreamId}
  AND operation_status IN ('RUNNING','UNKNOWN')

mapper.select:
SELECT tenant_id,user_id,tool_name,operation_id FROM side_effect_operations
WHERE operation_status='UNKNOWN' AND lookup_count < #{maxLookups}
  AND next_lookup <= #{now}
  AND tool_name IN

      #{tool}

ORDER BY next_lookup,downstream_id LIMIT #{limit}
